{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 10^5",
      "description": "The number of pillars is between 1 and 10^5, inclusive."
    },
    {
      "id": "P2",
      "expression": "0 <= d <= 10^9",
      "description": "The absolute difference threshold is between 0 and 10^9, inclusive."
    },
    {
      "id": "P3",
      "expression": "1 <= h[i] <= 10^15 for all i in 1..n",
      "description": "The height of each pillar is between 1 and 10^15, inclusive."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output_length == max_length",
      "description": "The output length of the jump sequence is the maximum possible length."
    },
    {
      "id": "Q2",
      "expression": "all(abs(h[sequence[i]] - h[sequence[i+1]]) >= d for i in 1..output_length-1)",
      "description": "The difference between the heights of consecutive pillars in the output sequence is at least d."
    },
    {
      "id": "Q3",
      "expression": "output_length == len(set(sequence))",
      "description": "The output sequence contains unique pillar indices."
    },
    {
      "id": "Q4",
      "expression": "sequence == any(sequence for sequence in all_sequences if len(sequence) == output_length)",
      "description": "The output sequence is one of the maximal length sequences."
    }
  ],
  "invariants": []
}
